/**
 * Get attendees for an event with optional filtering for checked-in only
 */
export const getEventAttendees = async (
  eventId: string, 
  includeProfiles = false
): Promise<any[]> => {
  try {
    let query = supabase
      .from("event_attendees_new")
      .select("*")
      .eq("event_id", eventId);
    
    if (includeProfiles) {
      // Instead of using the implicit join, we'll fetch profiles separately
      const { data: attendees, error } = await query;
      
      if (error) throw error;
      if (!attendees || attendees.length === 0) return [];
      
      // Get all user IDs from attendees
      const userIds = attendees.map(a => a.user_id);
      
      // Fetch profiles for these users
      const { data: profiles, error: profilesError } = await supabase
        .from("profiles")
        .select("*")
        .in("id", userIds);
      
      if (profilesError) throw profilesError;
      
      // Merge the data
      return attendees.map(attendee => {
        const profile = profiles?.find(p => p.id === attendee.user_id) || null;
        return { ...attendee, profile };
      });
    } else {
      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    }
  } catch (error) {
    console.error("Error getting event attendees:", error);
    throw error;
  }
};

